    $drawBar = { param($P, $G)
      $b = $script:bars[[string]$P.Tag]; if (-not $b) { return }
      $w = $P.ClientSize.Width; $h = $P.ClientSize.Height; if ($w -lt 4 -or $h -lt 4) { return }
      $G.Clear($trackColor)
