    $ci = $stepView.Columns.Add('Status', 'Status'); $stepView.Columns[$ci].AutoSizeMode = 'None'; $stepView.Columns[$ci].Width = 132; $stepView.Columns[$ci].SortMode = 'NotSortable'; $stepView.Columns[$ci].Tag = 'chip'
